import contextlib,hashlib,json,math,pathlib,sqlite3
def _path(path):
 path=pathlib.Path(path)
 if path.is_symlink():raise ValueError('queue symlink')
 return path
def _open(path):
 path=_path(path);path.parent.mkdir(parents=True,exist_ok=True);db=sqlite3.connect(path);db.execute('CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,payload TEXT NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL,due REAL NOT NULL,last_status INTEGER)');db.commit();return db
def _identity(payload):
 if not isinstance(payload,dict)or not isinstance(payload.get('groupKey'),str)or not payload['groupKey']or payload.get('status')not in('firing','resolved')or not isinstance(payload.get('alerts'),list)or not 1<=len(payload['alerts'])<=16:raise ValueError('payload')
 members=[]
 for a in payload['alerts']:
  if not isinstance(a,dict)or any(not isinstance(a.get(k),str)or not a[k]for k in('fingerprint','status','startsAt','endsAt'))or a['status']not in('firing','resolved'):raise ValueError('member')
  members.append([a['fingerprint'],a['status'],a['startsAt'],a['endsAt']])
 return hashlib.sha256(json.dumps({'groupKey':payload['groupKey'],'status':payload['status'],'members':sorted(members)},sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
def enqueue(path,payload):
 key=_identity(payload);text=json.dumps(payload,ensure_ascii=False,sort_keys=True)
 with contextlib.closing(_open(path))as db:
  with db:
   cursor=db.execute("INSERT OR IGNORE INTO jobs VALUES(?,?,'queued',0,0,NULL)",(key,text));created=cursor.rowcount==1
 return {'accepted':True,'id':key,'new':created}
def drain(path,now,send):
 if type(now)not in(int,float)or isinstance(now,float)and not math.isfinite(now)or now<0 or now>4102444800 or not callable(send):raise ValueError('drain arguments')
 attempted=0
 with contextlib.closing(_open(path))as db:
  rows=db.execute("SELECT id,payload,attempts FROM jobs WHERE state='queued' AND due<=? ORDER BY id",(now,)).fetchall()
  for key,text,previous in rows:
   count=previous+1
   try:status,headers=send(key,json.loads(text))
   except OSError:status,headers=503,{}
   attempted+=1
   if type(status)is not int or not isinstance(headers,dict):raise ValueError('channel response')
   if 200<=status<300:state,due='delivered',now
   elif status==429 or 500<=status<600:
    value=next((v for k,v in headers.items()if isinstance(k,str)and k.lower()=='retry-after'),'');delay=int(value)if isinstance(value,str)and value.isascii()and value.isdigit()and 1<=int(value)<=10 else 1;state,due=('dead'if count>=3 else'queued'),now
   else:state,due='dead',now
   with db:db.execute('UPDATE jobs SET state=?,attempts=?,due=?,last_status=? WHERE id=?',(state,count,due,status,key))
  counts={state:db.execute('SELECT count(*) FROM jobs WHERE state=?',(state,)).fetchone()[0]for state in('queued','delivered','dead')}
 return {'attempted':attempted,**counts}

